#include <stdio.h>

int main() {
    // do-while loop implementation
    // Printing the numbers 1 to 5
    printf("Post-test loop implementation\n");
    int i = 1;
    do {
        printf("%d\n", i);
        i++;
    } while (i <= 5);

    printf("Loop finished\n");

    return 0;
}

// Pseudo-ops and directives
